import{_ as p,a0 as r,w as o,s as d,ao as l,I as n,x as a,a1 as e,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"如何利用 SSL/TLS 保护你的 Linux 邮件服务 | LCTT x X-CMD","titleTemplate":false,"description":"如何利用 SSL/TLS 保护你的 Linux 邮件服务 | LCTT (202005) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何利用 SSL/TLS 保护你的 Linux 邮件服务 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何利用 SSL/TLS 保护你的 Linux 邮件服务 | LCTT (202005) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202005/20200427 How to secure your Linux email services with SSL-TLS","title":"如何利用 SSL/TLS 保护你的 Linux 邮件服务","tag":"202005","desc":""},"relativePath":"202005/20200427 How to secure your Linux email services with SSL-TLS.md","filePath":"[post].md"}'),h={name:"202005/20200427 How to secure your Linux email services with SSL-TLS.md"};function c(u,s,m,k,g,S){const i=r("Link");return o(),d("div",null,[s[25]||(s[25]=l('<h1 id="如何利用-ssl-tls-保护你的-linux-邮件服务" tabindex="-1">如何利用 SSL/TLS 保护你的 Linux 邮件服务 <a class="header-anchor" href="#如何利用-ssl-tls-保护你的-linux-邮件服务" aria-label="Permalink to “如何利用 SSL/TLS 保护你的 Linux 邮件服务”">​</a></h1><blockquote><p>通过理解安全证书来保护你的 Linux 邮件服务。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202005/13/215637khaogmririavnrlk.jpg" alt=""></p><p>通常，不管你是通过<ruby>简单邮件传输协议<rt>Simple Mail Transport Protocol</rt></ruby>（SMTP）或者<ruby>互联网消息访问协议<rt>Internet Message Access Protocol</rt></ruby>（IMAP）或<ruby>邮局协议<rt>Post Office Protocol</rt></ruby>（POP）发送或者接受邮件，邮件服务默认都是以无保护的明文来传输数据。近来随着数据加密成为越来越多程序的共识，你需要<ruby>安全套接层<rt>Secure Sockets Layer</rt></ruby>/<ruby>传输层安全性<rt>Transport Layer Security</rt></ruby>（SSL/TLS）的安全证书来保护你的邮件服务。</p><p>首先，快速回顾一下邮件服务和协议的基本流程。邮件通过 SMTP 从 TCP 端口 25 发出。这个协议依靠 DNS <ruby>邮件交换服务器<rt>Mail eXchanger</rt></ruby>（MX）记录的地址信息来传输邮件。当邮件到达邮件服务器后，可以被以下两种服务中的任意一种检索：使用 TCP 端口 143 的 IMAP，或者使用 TCP 端口 110 的 POP3（邮局协议第 3 版）。然而，以上服务都默认使用明文传输邮件和认证信息。这非常的不安全！</p>',5)),n("p",null,[s[1]||(s[1]=a("为了保护电子邮件数据和认证，这些服务都增加了一个安全功能，使它们可以利用 SSL/TLS 证书对数据流和通讯进行加密封装。SSL/TLS 是如何加密数据的细节不在本文讨论范围，有兴趣的话可以阅读 ",-1)),e(i,{href:"https://linux.cn/article-11699-1.html"},{default:t(()=>[...s[0]||(s[0]=[a("Bryant Son 关于互联网安全的文章",-1)])]),_:1}),s[2]||(s[2]=a("了解更多细节。概括的说，SSL/TLS 加密是一种基于公钥和私钥的算法。",-1))]),s[26]||(s[26]=l('<p>通过加入这些安全功能后，这些服务将监听在新的 TCP 端口：</p><div class="table-wrap"><table><thead><tr><th>服务</th><th>默认 TCP 端口</th><th>SSL/TLS 端口</th></tr></thead><tbody><tr><td>SMTP</td><td>25</td><td>587</td></tr><tr><td>IMAP</td><td>143</td><td>993</td></tr><tr><td>POP3</td><td>110</td><td>995</td></tr></tbody></table></div><h3 id="生成-ssl-tls-证书" tabindex="-1">生成 SSL/TLS 证书 <a class="header-anchor" href="#生成-ssl-tls-证书" aria-label="Permalink to “生成 SSL/TLS 证书”">​</a></h3>',3)),n("p",null,[e(i,{href:"https://www.openssl.org/"},{default:t(()=>[...s[3]||(s[3]=[a("OpenSSL",-1)])]),_:1}),s[4]||(s[4]=a(" 可以生成免费的 SSL/TLS 证书，或者你也可以从公共",-1)),s[5]||(s[5]=n("ruby",null,[a("证书颁发机构"),n("rt",null,"Certificate Authoritie")],-1)),s[6]||(s[6]=a("（CA）购买。过去，生成自签发证书十分简单而且通用，但是由于安全被日益重视，大部分的邮件客户端是不信任自签发证书的，除非手动设置。",-1))]),s[27]||(s[27]=l('<p>如果你只是自己使用或者做做测试，那就使用自签发证书省点钱吧。但是如果很多人或者客户也需要使用的话，那最好还是从受信任的证书颁发机构购买。</p><p>不管是哪种情况，开始请求新证书的过程是使用 Linux 系统上的 OpenSSL 工具来创建一个<ruby>证书签发请求<rt>Certificate Signing Request</rt></ruby>（CSR）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ openssl req -new -newkey rsa:2048 -nodes -keyout mail.mydomain.key -out mail.mydomain.csr</span></span></code></pre></div><p>这个命令会为你想保护的服务同时生成一个新的 CSR 文件和一个私匙。它会询问你一些证书相关的问题，如：位置、服务器的<ruby>完全合规域名<rt>Fully Qualified Domain Name</rt></ruby>（FQDN）、邮件联系信息等等。当你输入完这些信息后，私钥和 CSR 文件就生成完毕了。</p><h4 id="如果你想生成自签发证书" tabindex="-1">如果你想生成自签发证书 <a class="header-anchor" href="#如果你想生成自签发证书" aria-label="Permalink to “如果你想生成自签发证书”">​</a></h4>',5)),n("p",null,[s[8]||(s[8]=a("如果你想要生成自签发证书的话，在运行以上 CSR 命令之前，你必须先创建一个",-1)),e(i,{href:"https://en.wikipedia.org/wiki/Root_certificate"},{default:t(()=>[...s[7]||(s[7]=[a("自己的根 CA",-1)])]),_:1}),s[9]||(s[9]=a("。你可以通过以下方法创建自己的根 CA。",-1))]),s[28]||(s[28]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ openssl genrsa -des3 -out myCA.key 2048</span></span></code></pre></div><p>命令行会提示你输入一个密码。请输入一个复杂点的密码而且不要弄丢了，因为这将会是根 CA 私钥的密码，正如其名称所示，它是你的证书中所有信任关系的根。</p><p>接下来，生成根 CA 证书：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ openssl req -x509 -new -nodes -key myCA.key -sha256 -days 1825 -out myCA.pem</span></span></code></pre></div><p>在回答完一些问题后，你就拥有一个有效期为 5 年的根 CA 证书了。</p><p>用之前生成的 CSR 文件，你可以请求生成一个新证书，并由您刚才创建的根 CA 签名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ openssl x509 -req -in mail.mydomain.csr -CA myCA.pem -CAkey myCA.key -CAcreateserial -out mail.mydomain.pem -days 1825 -sha256</span></span></code></pre></div><p>输入你的根 CA 私钥的密码来创建和签署证书。</p><p>现在你有了配置电子邮件服务以增强安全性所需的两个文件：私匙文件 <code>mail.mydomain.key</code> 和公开证书文件 <code>mail.mydomain.pem</code>。</p><h4 id="如果你愿意购买证书" tabindex="-1">如果你愿意购买证书 <a class="header-anchor" href="#如果你愿意购买证书" aria-label="Permalink to “如果你愿意购买证书”">​</a></h4><p>如果你愿意从机构购买证书，则需要上传 CSR 文件到证书颁发机构的系统中，它将会被用于生成 SSL/TLS 证书。证书可作为文件下载，比如 <code>mail.mydomain.pem</code>。很多 SSL 机构也需要你下载一个中间证书。如果是这样的话，你必须把这个两个证书合并成一个，这样电子邮件服务就可以将这两个证书结合起来处理。可以使用以下命令把你的证书和第三方中间证书合并在一起：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat mail.mydomain.pem gd_bundle-g2-g1.crt &gt; mail.mydomain.pem</span></span></code></pre></div><p>值得一提的是 <code>.pem</code> 文件后缀代表<ruby>隐私增强邮件<rt>Privacy-Enhanced Mail</rt></ruby>。</p><p>现在你就有全部的设置邮件服务安全所需文件了：私匙文件 <code>mail.mydomain.key</code> 和组合的公开证书文件 <code>mail.mydomain.pem</code>。</p><h3 id="为你的文件生成一个安全的文件夹" tabindex="-1">为你的文件生成一个安全的文件夹 <a class="header-anchor" href="#为你的文件生成一个安全的文件夹" aria-label="Permalink to “为你的文件生成一个安全的文件夹”">​</a></h3><p>不管你是的证书是自签发的或者从机构购买，你都需要生成一个安全的，管理员拥有的文件夹用于保存这两个文件。可以使用以下命令来生成：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir /etc/pki/tls</span></span>
<span class="line"><span>$ chown root:root /etc/pki/tls</span></span>
<span class="line"><span>$ chmod 700 /etc/pki/tls</span></span></code></pre></div><p>在复制文件到 <code>/etc/pki/tls</code> 后，再次设置这些文件的权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod 600 /etc/pki/tls/*</span></span></code></pre></div><h3 id="配置你的-smtp-和-imap-服务" tabindex="-1">配置你的 SMTP 和 IMAP 服务 <a class="header-anchor" href="#配置你的-smtp-和-imap-服务" aria-label="Permalink to “配置你的 SMTP 和 IMAP 服务”">​</a></h3><p>接下来，让 SMTP 和 IMAP 服务使用新的安全证书。我们用 <code>postfix</code> 和 <code>dovecot</code> 来作为例子。</p><p>用你顺手的编辑器来编辑 <code>/etc/postfix/main.cf</code> 文件。添加以下几行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>smtpd_use_tls = yes</span></span>
<span class="line"><span>smtpd_tls_cert_file = /etc/pki/tls/mail.mydomain.pem</span></span>
<span class="line"><span>smtpd_tls_key_file = /etc/pki/tls/mail.mydomain.key</span></span></code></pre></div><h3 id="自定义选项" tabindex="-1">自定义选项 <a class="header-anchor" href="#自定义选项" aria-label="Permalink to “自定义选项”">​</a></h3><p>以下选项可以启用或禁用各种加密算法，协议等等：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>smtpd_tls_eecdh_grade = strong</span></span>
<span class="line"><span>smtpd_tls_protocols= !SSLv2, !SSLv3, !TLSv1, !TLSv1.1</span></span>
<span class="line"><span>smtpd_tls_mandatory_protocols= !SSLv2, !SSLv3, !TLSv1, !TLSv1.1</span></span>
<span class="line"><span>smtpd_tls_mandatory_ciphers = high</span></span>
<span class="line"><span>smtpd_tls_security_level=may</span></span>
<span class="line"><span>smtpd_tls_ciphers = high</span></span>
<span class="line"><span>tls_preempt_cipherlist = yes</span></span>
<span class="line"><span>smtpd_tls_mandatory_exclude_ciphers = aNULL, MD5 , DES, ADH, RC4, PSD, SRP, 3DES, eNULL</span></span>
<span class="line"><span>smtpd_tls_exclude_ciphers = aNULL, MD5 , DES, ADH, RC4, PSD, SRP, 3DES, eNULL</span></span>
<span class="line"><span>smtp_tls_mandatory_protocols = !SSLv2, !SSLv3, !TLSv1, !TLSv1.1</span></span>
<span class="line"><span>smtp_tls_protocols = !SSLv2, !SSLv3, !TLSv1, !TLSv1.1</span></span></code></pre></div><p>编辑 <code>/etc/dovecot/dovecot.conf</code> 文件，添加以下三行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ssl = required</span></span>
<span class="line"><span>ssl_cert = &amp;lt;/etc/pki/tls/mail.mydomain.pem</span></span>
<span class="line"><span>ssl_key = &amp;lt;/etc/pki/tls/mail.mydomain.key</span></span></code></pre></div><p>添加下列更多选项来启用或禁用各种加密算法、协议等等（我把这些留给你来理解）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ssl_cipher_list = EECDH+ECDSA+AESGCM:EECDH+aRSA+AESGCM:EECDH+ECDSA+SHA384:EECDH+ECDSA+SHA256:EECDH+aRSA+SHA384:EECDH+aRSA+SHA256:EECDH+aRSA+RC4:EECDH:EDH+aRSA:ALL:!aNULL:!eNULL:!LOW:!3DES:!MD5:!EXP:!PSK:!SRP:!DSS:!RC4:!SSLv2</span></span>
<span class="line"><span>ssl_prefer_server_ciphers = yes</span></span>
<span class="line"><span>ssl_protocols = !SSLv2 !SSLv3 !TLSv1 !TLSv1.1</span></span>
<span class="line"><span>ssl_min_protocol = TLSv1.2</span></span></code></pre></div><h3 id="设置-selinux-上下文" tabindex="-1">设置 SELinux 上下文 <a class="header-anchor" href="#设置-selinux-上下文" aria-label="Permalink to “设置 SELinux 上下文”">​</a></h3><p>如果你的 Linux 发行版启用了 SELinux，请为你的新证书文件设置正确的 SELinux 上下文。</p><p>对于 Postfix 设置 SELinux：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chcon -u system_u -t cert_t mail.mydomain.*</span></span></code></pre></div><p>对于 Dovecot 设置 SELinux：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chcon -u system_u -t dovecot_cert_t mail.mydomain.*</span></span></code></pre></div><p>重启这些服务，并与你相应更新过的电子邮件客户端配置连接。有些电子邮件客户端会自动探测到新的端口，有些则需要你手动更新。</p><h3 id="测试配置" tabindex="-1">测试配置 <a class="header-anchor" href="#测试配置" aria-label="Permalink to “测试配置”">​</a></h3><p>用 <code>openssl</code> 命令行和 <code>s_client</code> 插件来简单测试一下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ openssl s_client -connect mail.mydomain.com:993</span></span>
<span class="line"><span>$ openssl s_client -starttls imap -connect mail.mydomain.com:143</span></span>
<span class="line"><span>$ openssl s_client -starttls smtp -connect mail.mydomain.com:587</span></span></code></pre></div><p>这些测试命令会打印出很多信息，关于你使用的连接、证书、加密算法、会话和协议。这不仅是一个验证新设置的好方法，也可以确认你使用了适当的证书，以及在 postfix 或 dovecot 配置文件中定义的安全设置正确。</p><p>保持安全！</p><hr>`,43)),n("p",null,[s[11]||(s[11]=a("via: ",-1)),e(i,{href:"https://opensource.com/article/20/4/securing-linux-email"},{default:t(()=>[...s[10]||(s[10]=[a("https://opensource.com/article/20/4/securing-linux-email",-1)])]),_:1})]),n("p",null,[s[16]||(s[16]=a("作者：",-1)),e(i,{href:"https://opensource.com/users/marc-skinner"},{default:t(()=>[...s[12]||(s[12]=[a("Marc Skinner",-1)])]),_:1}),s[17]||(s[17]=a(" 选题：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[13]||(s[13]=[a("lujun9972",-1)])]),_:1}),s[18]||(s[18]=a(" 译者：",-1)),e(i,{href:"https://github.com/Acceleratorrrr"},{default:t(()=>[...s[14]||(s[14]=[a("Acceleratorrrr",-1)])]),_:1}),s[19]||(s[19]=a(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:t(()=>[...s[15]||(s[15]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[22]||(s[22]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[20]||(s[20]=[a("LCTT",-1)])]),_:1}),s[23]||(s[23]=a(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:t(()=>[...s[21]||(s[21]=[a("Linux中国",-1)])]),_:1}),s[24]||(s[24]=a(" 荣誉推出",-1))])])}const C=p(h,[["render",c]]);export{L as __pageData,C as default};
